"""Reticulum + LXMF presence for the Ratspeak MCP connector.

Private keys are persisted under the data directory and are NEVER returned
by any public method or logged.
"""

from __future__ import annotations

import json
import os
import threading
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import LXMF
import RNS

DEFAULT_HOME = Path("/home/box/.ratspeak-mcp")
DEFAULT_DISPLAY_NAME = "Rat"
DEFAULT_TCP_HOST = "2.ratspeak.org"
DEFAULT_TCP_PORT = 4242
INBOX_LIMIT = 200

RNS_CONFIG_TEMPLATE = """\
# Generated by ratspeak-mcp — do not put secrets here.
# Identity private keys live in identity/ under the data dir, not in this file.

[reticulum]
  enable_transport = No
  share_instance = Yes
  instance_name = ratspeak-mcp

[logging]
  loglevel = 3

[interfaces]
  [[Emerald]]
    type = TCPClientInterface
    enabled = yes
    target_host = {host}
    target_port = {port}
"""


def data_home() -> Path:
    env = os.environ.get("RATSPEAK_MCP_HOME")
    if env:
        return Path(env).expanduser().resolve()
    return DEFAULT_HOME


def _hex(h: bytes | None) -> str | None:
    if h is None:
        return None
    return h.hex()


@dataclass
class StoredMessage:
    message_id: str
    source_hash: str | None
    destination_hash: str | None
    title: str
    content: str
    timestamp: float
    signature_validated: bool
    direction: str  # "inbound" | "outbound"

    def to_dict(self) -> dict[str, Any]:
        return {
            "message_id": self.message_id,
            "source_hash": self.source_hash,
            "destination_hash": self.destination_hash,
            "title": self.title,
            "content": self.content,
            "timestamp": self.timestamp,
            "signature_validated": self.signature_validated,
            "direction": self.direction,
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "StoredMessage":
        return cls(
            message_id=d["message_id"],
            source_hash=d.get("source_hash"),
            destination_hash=d.get("destination_hash"),
            title=d.get("title") or "",
            content=d.get("content") or "",
            timestamp=float(d.get("timestamp") or 0),
            signature_validated=bool(d.get("signature_validated")),
            direction=d.get("direction") or "inbound",
        )


@dataclass
class RatspeakBridge:
    display_name: str = DEFAULT_DISPLAY_NAME
    tcp_host: str = DEFAULT_TCP_HOST
    tcp_port: int = DEFAULT_TCP_PORT
    home: Path = field(default_factory=data_home)

    _lock: threading.RLock = field(default_factory=threading.RLock, init=False, repr=False)
    _started: bool = field(default=False, init=False)
    _reticulum: Any = field(default=None, init=False, repr=False)
    _router: Any = field(default=None, init=False, repr=False)
    _identity: Any = field(default=None, init=False, repr=False)
    _destination: Any = field(default=None, init=False, repr=False)
    _inbox: list[StoredMessage] = field(default_factory=list, init=False)
    _last_announce: float | None = field(default=None, init=False)
    _start_error: str | None = field(default=None, init=False)
    _first_run: bool = field(default=False, init=False)

    @property
    def rns_dir(self) -> Path:
        return self.home / "rns"

    @property
    def lxmf_dir(self) -> Path:
        return self.home / "lxmf"

    @property
    def identity_path(self) -> Path:
        return self.home / "identity" / "lxmf_identity"

    @property
    def inbox_path(self) -> Path:
        return self.home / "inbox.json"

    @property
    def dest_hash_path(self) -> Path:
        return self.home / "destination_hash.txt"

    @property
    def destination_hash(self) -> str | None:
        if self._destination is None:
            return None
        return _hex(self._destination.hash)

    def ensure_layout(self) -> None:
        self.home.mkdir(parents=True, exist_ok=True)
        (self.home / "identity").mkdir(parents=True, exist_ok=True)
        self.rns_dir.mkdir(parents=True, exist_ok=True)
        self.lxmf_dir.mkdir(parents=True, exist_ok=True)
        config_path = self.rns_dir / "config"
        if not config_path.exists():
            self._first_run = True
            config_path.write_text(
                RNS_CONFIG_TEMPLATE.format(host=self.tcp_host, port=self.tcp_port),
                encoding="utf-8",
            )
        if self.inbox_path.exists():
            try:
                raw = json.loads(self.inbox_path.read_text(encoding="utf-8"))
                self._inbox = [StoredMessage.from_dict(x) for x in raw]
            except Exception:
                self._inbox = []

    def _persist_inbox(self) -> None:
        payload = [m.to_dict() for m in self._inbox[-INBOX_LIMIT:]]
        self.inbox_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")

    def _write_destination_hash_file(self) -> None:
        h = self.destination_hash
        if h:
            self.dest_hash_path.write_text(h + "\n", encoding="utf-8")

    def _load_or_create_identity(self) -> Any:
        path = self.identity_path
        if path.exists():
            identity = RNS.Identity.from_file(str(path))
            if identity is None:
                raise RuntimeError(f"Failed to load identity from {path}")
            return identity
        self._first_run = True
        identity = RNS.Identity()
        if not identity.to_file(str(path)):
            raise RuntimeError(f"Failed to persist identity to {path}")
        # Restrictive permissions on private key material
        try:
            os.chmod(path, 0o600)
            os.chmod(path.parent, 0o700)
        except OSError:
            pass
        return identity

    def _on_delivery(self, message: Any) -> None:
        try:
            mid = _hex(getattr(message, "hash", None)) or f"in-{time.time_ns()}"
            stored = StoredMessage(
                message_id=mid,
                source_hash=_hex(getattr(message, "source_hash", None)),
                destination_hash=_hex(getattr(message, "destination_hash", None)),
                title=str(message.title_as_string() or ""),
                content=str(message.content_as_string() or ""),
                timestamp=float(getattr(message, "timestamp", None) or time.time()),
                signature_validated=bool(getattr(message, "signature_validated", False)),
                direction="inbound",
            )
            with self._lock:
                self._inbox.append(stored)
                if len(self._inbox) > INBOX_LIMIT:
                    self._inbox = self._inbox[-INBOX_LIMIT:]
                self._persist_inbox()
            # Optional webhook wake for allowlisted peers (soft-fail; never crash mesh).
            try:
                from ratspeak_mcp.webhook import maybe_fire_inbound_webhook

                maybe_fire_inbound_webhook(
                    home=self.home,
                    message_id=stored.message_id,
                    source_hash=stored.source_hash,
                    destination_hash=stored.destination_hash,
                    title=stored.title,
                    content=stored.content,
                    timestamp=stored.timestamp,
                )
            except Exception as we:
                RNS.log(f"ratspeak-mcp webhook error: {we}", RNS.LOG_WARNING)
        except Exception as e:
            RNS.log(f"ratspeak-mcp inbox store error: {e}", RNS.LOG_ERROR)

    def start(self, announce: bool = True, wait_tcp_seconds: float = 6.0) -> None:
        with self._lock:
            if self._started:
                return
            self.ensure_layout()
            try:
                # Keep RNS logs off stdout so MCP stdio stays clean.
                self._reticulum = RNS.Reticulum(
                    configdir=str(self.rns_dir),
                    loglevel=RNS.LOG_NOTICE,
                    logdest=RNS.LOG_FILE,
                )
                self._identity = self._load_or_create_identity()
                self._router = LXMF.LXMRouter(storagepath=str(self.lxmf_dir))
                self._destination = self._router.register_delivery_identity(
                    self._identity,
                    display_name=self.display_name,
                )
                self._router.register_delivery_callback(self._on_delivery)
                self._write_destination_hash_file()
                self._started = True
            except Exception as e:
                self._start_error = str(e)
                raise

        # Wait briefly for TCP so status is meaningful on first start.
        deadline = time.time() + wait_tcp_seconds
        while time.time() < deadline:
            if self._tcp_online():
                break
            time.sleep(0.25)

        if announce:
            try:
                self.announce()
            except Exception as e:
                # Non-fatal: presence is up even if announce fails without path yet.
                RNS.log(f"ratspeak-mcp initial announce: {e}", RNS.LOG_WARNING)

    def _tcp_online(self) -> bool:
        try:
            for iface in RNS.Transport.interfaces:
                if getattr(iface, "online", False):
                    name = str(getattr(iface, "name", "") or "")
                    if "Emerald" in name or type(iface).__name__ == "TCPClientInterface":
                        return True
            return False
        except Exception:
            return False

    def interface_status(self) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        try:
            for iface in RNS.Transport.interfaces:
                out.append(
                    {
                        "name": str(getattr(iface, "name", type(iface).__name__)),
                        "type": type(iface).__name__,
                        "online": bool(getattr(iface, "online", False)),
                        "never_connected": bool(getattr(iface, "never_connected", False)),
                        "reconnecting": bool(getattr(iface, "reconnecting", False)),
                    }
                )
        except Exception as e:
            out.append({"error": str(e)})
        return out

    def status(self) -> dict[str, Any]:
        return {
            "started": self._started,
            "display_name": self.display_name,
            "destination_hash": self.destination_hash,
            "data_home": str(self.home),
            "tcp_target": f"{self.tcp_host}:{self.tcp_port}",
            "tcp_online": self._tcp_online() if self._started else False,
            "interfaces": self.interface_status() if self._started else [],
            "last_announce": self._last_announce,
            "inbox_count": len(self._inbox),
            "first_run": self._first_run,
            "start_error": self._start_error,
            "destination_hash_file": str(self.dest_hash_path),
        }

    def identity_info(self) -> dict[str, Any]:
        """Public identity info only — never private keys."""
        return {
            "display_name": self.display_name,
            "destination_hash": self.destination_hash,
            "destination_hash_file": str(self.dest_hash_path),
            "note": "Share destination_hash with peers. Private keys are never exposed.",
        }

    def announce(self) -> dict[str, Any]:
        if not self._started or self._destination is None or self._router is None:
            raise RuntimeError("Bridge not started")
        self._router.announce(self._destination.hash)
        self._last_announce = time.time()
        return {
            "ok": True,
            "destination_hash": self.destination_hash,
            "announced_at": self._last_announce,
            "tcp_online": self._tcp_online(),
        }

    def send(
        self,
        dest_hash: str,
        body: str,
        subject: str | None = None,
        path_timeout: float = 20.0,
    ) -> dict[str, Any]:
        if not self._started or self._destination is None or self._router is None:
            raise RuntimeError("Bridge not started")

        dest_hash = dest_hash.strip().lower().replace(":", "")
        if len(dest_hash) != 32:
            raise ValueError("dest_hash must be a 32-character hex destination hash")
        recipient_hash = bytes.fromhex(dest_hash)

        if not RNS.Transport.has_path(recipient_hash):
            RNS.Transport.request_path(recipient_hash)
            deadline = time.time() + path_timeout
            while time.time() < deadline and not RNS.Transport.has_path(recipient_hash):
                time.sleep(0.2)
            if not RNS.Transport.has_path(recipient_hash):
                raise TimeoutError(
                    f"No path to {dest_hash} within {path_timeout}s. "
                    "Peer may be offline or not announced on this mesh."
                )

        recipient_identity = RNS.Identity.recall(recipient_hash)
        if recipient_identity is None:
            raise RuntimeError(f"Could not recall identity for {dest_hash}")

        dest = RNS.Destination(
            recipient_identity,
            RNS.Destination.OUT,
            RNS.Destination.SINGLE,
            "lxmf",
            "delivery",
        )
        title = subject or ""
        lxm = LXMF.LXMessage(
            dest,
            self._destination,
            body,
            title,
            desired_method=LXMF.LXMessage.DIRECT,
            include_ticket=True,
        )
        delivery = {"event": threading.Event(), "state": None}

        def _on_delivery(msg: Any) -> None:
            delivery["state"] = getattr(msg, "state", None)
            delivery["event"].set()

        try:
            lxm.register_delivery_callback(_on_delivery)
        except Exception:
            pass

        self._router.handle_outbound(lxm)

        # Wait for LXMF delivery proof when possible (DIRECT=2 -> DELIVERED=8).
        delivery_timeout = float(os.environ.get("RATSPEAK_DELIVERY_TIMEOUT", "45"))
        delivery["event"].wait(delivery_timeout)
        final_state = delivery["state"] if delivery["state"] is not None else getattr(lxm, "state", None)
        delivered = final_state == getattr(LXMF.LXMessage, "DELIVERED", 8)

        mid = _hex(getattr(lxm, "hash", None)) or f"out-{time.time_ns()}"
        stored = StoredMessage(
            message_id=mid,
            source_hash=self.destination_hash,
            destination_hash=dest_hash,
            title=title,
            content=body,
            timestamp=time.time(),
            signature_validated=True,
            direction="outbound",
        )
        with self._lock:
            self._inbox.append(stored)
            if len(self._inbox) > INBOX_LIMIT:
                self._inbox = self._inbox[-INBOX_LIMIT:]
            self._persist_inbox()

        method_val = getattr(lxm, "method", None)
        method_name = {
            getattr(LXMF.LXMessage, "OPPORTUNISTIC", 1): "OPPORTUNISTIC",
            getattr(LXMF.LXMessage, "DIRECT", 2): "DIRECT",
            getattr(LXMF.LXMessage, "PROPAGATED", 3): "PROPAGATED",
        }.get(method_val, str(method_val))

        return {
            "ok": bool(delivered),
            "message_id": mid,
            "dest_hash": dest_hash,
            "subject": title,
            "method": method_name,
            "lxmf_state": final_state,
            "delivered": bool(delivered),
        }

    def inbox(self, limit: int = 20) -> list[dict[str, Any]]:
        with self._lock:
            items = list(self._inbox[-max(1, limit) :])
        items.reverse()  # newest first
        return [m.to_dict() for m in items]

    def read(self, message_id: str) -> dict[str, Any]:
        with self._lock:
            for m in self._inbox:
                if m.message_id == message_id:
                    return m.to_dict()
        raise KeyError(f"No message with id {message_id}")


_bridge: RatspeakBridge | None = None
_bridge_lock = threading.Lock()


def get_bridge() -> RatspeakBridge:
    global _bridge
    with _bridge_lock:
        if _bridge is None:
            display = os.environ.get("RATSPEAK_MCP_DISPLAY_NAME", DEFAULT_DISPLAY_NAME)
            host = os.environ.get("RATSPEAK_MCP_TCP_HOST", DEFAULT_TCP_HOST)
            port = int(os.environ.get("RATSPEAK_MCP_TCP_PORT", str(DEFAULT_TCP_PORT)))
            _bridge = RatspeakBridge(display_name=display, tcp_host=host, tcp_port=port)
            _bridge.start(announce=True)
        return _bridge
